        failures = []
        if 'path' not in inputs:
            failures.append(provider_pb2.CheckFailure(
                property='path',
                reason='path is required'
            ))
        if 'content' not in inputs:
            failures.append(provider_pb2.CheckFailure(
                property='content',
                reason='content is required'
            ))

