    name='my-network-stack'
)

subnet_id = network.outputs['SubnetId']

web = aws.ec2.Instance('web',
    ami='ami-0adc0e3ef2558cb1f', # us-west-2 AMI
    instance_type='t2.micro',
    subnet_id=subnet_id
)
```

